import re

HEAD = re.compile(r"^(?P<level>#+) (?P<title>\S.*?)\s*$")
FENCE = re.compile(r"^```")
KV = re.compile(r"^(?P<indent>\s*)(?P<key>\S(?:.*?\S)?)(?:\s{2,}(?P<value>\S.*?))?\s*$")


def parse(lines):
    env, files, e_lines, f_lines, skip = [], [], [], [], []
    section, level, parent, n = "", 0, "", 0
    for j, ln in enumerate(lines):
        if not ln.strip():
            continue
        m = HEAD.match(ln)
        if m:
            section, level, parent, n = m.group("title"), len(m.group("level")), "", 0
            (f_lines if level >= 3 else e_lines).append(j)
            continue
        if FENCE.match(ln):
            skip.append(j)
            continue
        if level >= 3:
            n += 1
            files.append({"file": section, "line": n, "content": ln})
            f_lines.append(j)
            continue
        m = KV.match(ln)
        if m:
            if m.group("indent"):
                env.append({"section": section, "parent": parent, "key": m.group("key"),
                            "value": m.group("value") or ""})
            else:
                parent = m.group("key")
                env.append({"section": section, "parent": "", "key": parent, "value": m.group("value") or ""})
            e_lines.append(j)
    return {"blocks": [{"name": "environment", "kind": "table", "lines": e_lines, "records": env},
                       {"name": "files", "kind": "table", "lines": f_lines, "records": files}],
            "skip": skip}
